from produire import produire,paras,table,steps
parts=[
('La xérostomie médicamenteuse est une sensation de bouche sèche favorisée par un traitement. Les {distinctions utiles} évitent de confondre plainte subjective et baisse mesurée du débit salivaire.',paras('Une hyposialie peut accompagner la xérostomie, mais les deux ne sont pas identiques. L’imputabilité médicamenteuse repose sur chronologie, mécanisme et recherche d’autres causes.')),
('La polymédication augmente le risque de sécheresse. Les {expositions pertinentes} ne se limitent pas à un médicament nouvellement introduit.',paras('L’effet cumulatif de plusieurs traitements à activité anticholinergique peut être important. Psychotropes, traitements de la vessie et certains antalgiques sont notamment à rechercher ; la déshydratation et les maladies associées peuvent s’ajouter.')),
('Les médicaments peuvent diminuer la sécrétion ou modifier la perception de sécheresse. Les {conséquences salivaires} expliquent le retentissement dentaire et alimentaire.',paras('La baisse de lubrification gêne mastication, déglutition, parole et port de prothèse. La perte de protection salivaire favorise caries, irritation et candidose.')),
('Une bouche sèche ne doit pas masquer une urgence ou une maladie systémique. Les {signes d’alarme} orientent le bilan.',paras('Déshydratation importante, incapacité à boire, trouble de conscience ou dysphagie nouvelle imposent une évaluation rapide. Masse glandulaire, ulcère persistant, amaigrissement ou symptômes systémiques ne doivent pas être attribués automatiquement au médicament.')),
('L’entretien reconstruit traitements, doses et dates. Les {questions d’imputabilité} incluent produits sans ordonnance et changements récents.',paras('Comparer début des symptômes à introduction ou augmentation de dose ; rechercher plusieurs substances ayant un effet similaire. Demander soif, polyurie, yeux secs, radiothérapie, respiration buccale nocturne et symptômes de candidose.')),
('L’examen apprécie salive, muqueuses, dents et prothèses. Les {constats utiles} mesurent le retentissement au-delà de la plainte.',paras('Rechercher salive rare ou filante, langue et muqueuses sèches, caries, irritation et plaques candidosiques. Examiner glandes et ganglions ; une bouche paraissant humide n’invalide pas la sensation rapportée.')),
('Le {diagnostic différentiel} reste indispensable même en présence d’un médicament connu. Plusieurs causes peuvent coexister.',table(['Contexte','Cause à rechercher'],[['Yeux secs et signes systémiques.','Maladie de Sjögren.'],['Polyurie et soif.','Trouble métabolique, notamment diabète selon le contexte.'],['Radiothérapie de la tête et du cou.','Atteinte glandulaire post-thérapeutique.'],['Fièvre, pertes liquidiennes ou apports réduits.','Déshydratation.'],['Sécheresse surtout nocturne.','Respiration buccale ou autre facteur local.']])) ,
('Aucun test unique ne prouve l’origine médicamenteuse. Les {arguments positifs} doivent être concordants.',paras('Chronologie plausible, mécanisme connu, charge médicamenteuse et amélioration après adaptation encadrée soutiennent l’hypothèse. Ne pas provoquer une interruption risquée uniquement pour confirmer le diagnostic.')),
('Le bilan est adapté au contexte et au retentissement. Les {examens ciblés} évitent une recherche immunologique systématique sans argument.',paras('Une mesure salivaire peut objectiver l’hyposialie. Bilan métabolique, immunologique ou spécialisé selon symptômes associés ; le contrôle dentaire évalue les complications et la prévention nécessaire.')),
('L’{arbre de prise en charge} associe revue médicamenteuse et protection buccale. Toute modification doit préserver le bénéfice du traitement initial.',steps('Évaluer hydratation, complications et signes atypiques.', 'Rassembler la liste complète des médicaments et rechercher les effets cumulatifs.', 'Avec le prescripteur et le pharmacien, envisager diminution, substitution ou adaptation lorsqu’elles sont possibles.', 'Proposer mesures symptomatiques et suivi dentaire, puis mesurer l’évolution et rechercher une autre cause si persistance.')),
('La prise en charge commence par des mesures locales et une revue du traitement. Les {options pratiques} sont choisies selon salivation résiduelle et sécurité de déglutition.',paras('Petites prises de boisson adaptées, substituts salivaires et stimulation par produits sans sucre peuvent aider ; éviter les aliments ou boissons acides répétés. Une mastication stimulante n’est pas appropriée si elle expose à une fausse route.', 'Salagen a des indications suisses pour Sjögren et certaines xérostomies post-radiothérapie, pas pour toute sécheresse médicamenteuse. Son emploi éventuel hors de ces indications exige une décision spécifique ; il ne remplace pas la revue médicamenteuse.')),
('La {prévention dentaire} est centrale dans une sécheresse durable. Les mesures doivent être adaptées au niveau de risque carieux.',paras('Hygiène douce avec dentifrice fluoré et suivi dentaire régulier ; le dentiste peut renforcer la prévention selon l’hyposialie. Éviter de compenser la sécheresse par grignotage sucré et boissons acides ; entretenir les prothèses et traiter les lésions associées.')),
('La chronologie médicamenteuse oriente sans prouver à elle seule la cause. Aucun traitement essentiel ne doit être arrêté sans encadrement. Protection dentaire, confort et recherche de causes associées doivent avancer ensemble.','')]
quiz=[('Xérostomie et hyposialie sont-elles synonymes ?','Non : sensation subjective et débit mesuré diffèrent.'),('Un médicament ancien peut-il encore contribuer ?','Oui, notamment par cumul ou modification du terrain.'),('Faut-il recenser les produits sans ordonnance ?','Oui.'),('La charge anticholinergique peut-elle être cumulative ?','Oui.'),('Faut-il arrêter seul un psychotrope pour tester la cause ?','Non : adaptation encadrée avec le prescripteur.'),('Une bouche visuellement humide exclut-elle la plainte ?','Non.'),('Quels signes orientent vers Sjögren ?','Sécheresse oculaire associée et arguments systémiques, à confirmer par un bilan adapté.'),('Polyurie et soif évoquent-elles uniquement un médicament ?','Non : rechercher notamment une cause métabolique.'),('Quelle complication dentaire augmente avec l’hyposialie ?','Le risque carieux.'),('Une candidose peut-elle être favorisée ?','Oui.'),('Les boissons acides répétées sont-elles une bonne prévention ?','Non : elles peuvent irriter et favoriser l’érosion dentaire.'),('Un produit à mâcher convient-il à toute dysphagie ?','Non : il faut vérifier la sécurité de déglutition.'),('La pilocarpine est-elle autorisée pour toute sécheresse médicamenteuse ?','Non : les indications suisses citées sont spécifiques.'),('Que faire si la sécheresse persiste malgré adaptation ?','Réévaluer retentissement, observance des mesures et causes associées.')]
produire(6,parts,quiz,(1,2,8,15,18,21))
